let input = msg.payload;
if (typeof input === 'string') {
    try {
        input = JSON.parse(input);
    } catch (error) {
        node.error('Payload must be valid JSON', msg);
        return null;
    }
}

const port = Number(input && input.port);
const message = String(input && (input.message || input.payload) || '')
    .replace(/\s+/g, '')
    .toUpperCase();

if (!Number.isInteger(port) || port < 1 || port > 223) {
    node.error('port must be an integer from 1 through 223', msg);
    return null;
}
if (!/^[0-9A-F]+$/.test(message) || message.length % 2 !== 0) {
    node.error('message must be even-length HEX', msg);
    return null;
}
const bytes = message.match(/../g).map(value => parseInt(value, 16));
if (bytes.length < 4 || bytes.length > 51) {
    node.error('OTA message must contain 4 through 51 bytes', msg);
    return null;
}
if (bytes[1] !== 1) {
    node.error('Unsupported OTA protocol version ' + bytes[1], msg);
    return null;
}
let crc = 0;
for (const value of bytes.slice(0, -1)) {
    crc ^= value;
    for (let bit = 0; bit < 8; bit += 1) {
        crc = crc & 0x80 ? ((crc << 1) ^ 0x07) & 0xFF : (crc << 1) & 0xFF;
    }
}
if (crc !== bytes[bytes.length - 1]) {
    node.error('OTA CRC mismatch', msg);
    return null;
}

const baseUrl = env.get('ACAP_BASE_URL') || 'http://back.internal';
msg._otaRequest = { port, message };
msg.method = 'POST';
msg.url = baseUrl.replace(/\/$/, '') + '/local/aib100/b100_receive';
msg.headers = { 'content-type': 'application/json' };
msg.payload = {
    port,
    length: bytes.length,
    payload: message,
    payload_type: 'HEX',
    next_upload_ms: 0
};
return msg;

const accepted = msg.statusCode >= 200 && msg.statusCode < 300;
msg.payload = {
    accepted,
    statusCode: msg.statusCode,
    acapResponse: msg.payload,
    request: msg._otaRequest
};
delete msg.headers;
delete msg.responseUrl;
return msg.res ? [msg, msg] : [null, msg];

msg.statusCode = 400;
msg.payload = { accepted: false, error: msg.error.message };
return msg.res ? [msg, msg] : [null, msg];
